import ast
import os
import re
import subprocess
import sys
import tempfile
import time
import tomllib
from dataclasses import dataclass, field
from typing import Any, Dict, List, Optional, Tuple

# Constants
SKIPPED = 'skipped'
PASSED = 'passed'
FAILED = 'failed'
DEFAULT_PENALTY_PER_GATE = 6.25
DEFAULT_TIMEOUT_S = 60

# Import artifacts module for filtering logic
try:
    from hae.evaluation.artifacts import filter_bundle, is_generated_path, is_malformed_path
except ImportError:
    # Fallback if artifacts is not yet available or in a different path structure
    # This ensures the harness can still run if artifacts is missing, though it's expected to be present.
    def filter_bundle(bundle: Dict[str, str]) -> Dict[str, str]:
        return bundle
    def is_generated_path(path: str) -> bool:
        return False
    def is_malformed_path(path: str) -> bool:
        return False


@dataclass
class GateResult:
    """Outcome of a single verification gate."""
    name: str
    status: str
    method: str
    detail: str = ''
    duration_s: float = 0.0
    evidence: Dict[str, Any] = field(default_factory=dict)

    @property
    def passed(self) -> bool:
        return self.status == PASSED

    @property
    def evaluated(self) -> bool:
        return self.status != SKIPPED


@dataclass
class VerificationReport:
    """Aggregate result across all gates."""
    gates: List[GateResult]
    score_penalty: float
    authored_files: int
    python_files: int
    source: str = 'bundle'
    harness_version: str = '3.0-execution'

    def gate(self, name: str) -> Optional[GateResult]:
        for g in self.gates:
            if g.name == name:
                return g
        return None

    @property
    def evaluated_gates(self) -> List[GateResult]:
        return [g for g in self.gates if g.evaluated]

    @property
    def passed_gates(self) -> List[GateResult]:
        return [g for g in self.gates if g.passed]

    @property
    def gate_status(self) -> Dict[str, str]:
        """Gate name -> PASSED | FAILED | SKIPPED. The fitness function's input."""
        return {g.name: g.status for g in self.gates}

    @property
    def gate_detail(self) -> Dict[str, str]:
        return {g.name: g.detail for g in self.gates}

    @property
    def pass_rate(self) -> float:
        """Fraction of *evaluated* gates that passed. Skips are excluded."""
        evaluated = self.evaluated_gates
        if not evaluated:
            return 0.0
        passed = [g for g in evaluated if g.passed]
        return len(passed) / len(evaluated)

    def summary(self) -> str:
        lines = [f"Verification Report ({self.source})"]
        lines.append(f"Authored Files: {self.authored_files} (Python: {self.python_files})")
        lines.append(f"Score Penalty: {self.score_penalty:.2f}")
        lines.append("-" * 40)
        for g in self.gates:
            status_icon = "✅" if g.passed else ("⏭️" if g.status == SKIPPED else "❌")
            lines.append(f"{status_icon} {g.name}: {g.status.upper()} ({g.method})")
            if g.detail:
                lines.append(f"   Detail: {g.detail}")
        return "\n".join(lines)

    def to_dict(self) -> Dict[str, Any]:
        return {
            "gates": [
                {
                    "name": g.name,
                    "status": g.status,
                    "method": g.method,
                    "detail": g.detail,
                    "duration_s": g.duration_s,
                    "evidence": g.evidence
                }
                for g in self.gates
            ],
            "score_penalty": self.score_penalty,
            "authored_files": self.authored_files,
            "python_files": self.python_files,
            "source": self.source,
            "harness_version": self.harness_version,
            "pass_rate": self.pass_rate,
            "gate_status": self.gate_status
        }


def extract_code_blocks(text: str) -> Dict[str, str]:
    """Recovers a path->content map from fenced code blocks in a deliverable.

    A last resort, used only when a firm produced no live workspace. Only the
    contents of fenced blocks are returned; the surrounding prose is discarded
    and never reaches a gate.
    """
    if not text:
        return {}

    # Regex to match fenced code blocks with optional language and optional filename hint
    # Pattern: ```[language] [filename]\ncontent\n```
    # We look for blocks that might contain a filename in the info string or just assume sequential naming if not found.
    # However, the spec implies recovering a path->content map. 
    # Common convention in these deliverables is ```python path/to/file.py

    blocks = {}
    # Match ``` followed by optional info string, then content, then ```
    pattern = r"```(?:\s*([^\n]*))?\n(.*?)\n```"
    matches = re.finditer(pattern, text, re.DOTALL)

    counter = 0
    for match in matches:
        info_string = match.group(1) or ""
        content = match.group(2)

        # Try to extract a filename from the info string
        # e.g., "python src/main.py" or just "src/main.py"
        filename = None
        parts = info_string.split()
        for part in parts:
            if '.' in part and not part.startswith('-'): # Heuristic for filename
                # Check if it looks like a path
                if '/' in part or '\\' in part or part.endswith('.py'):
                    filename = part
                    break

        if not filename:
            # Fallback: generate a name
            filename = f"extracted_block_{counter}.py"
            counter += 1

        # Normalize path separators
        filename = filename.replace('\\', '/')

        # Only keep .py files for the bundle if we are extracting code for verification
        # But the function returns a generic map. The harness will filter.
        blocks[filename] = content

    return blocks


class ExecutionHarness:
    """Materializes a workspace bundle and verifies it by actually running it."""

    def __init__(self, timeout_s: int=DEFAULT_TIMEOUT_S, penalty_per_gate: float=DEFAULT_PENALTY_PER_GATE, python_executable: Optional[str]=None):
        self.timeout_s = timeout_s
        self.penalty_per_gate = penalty_per_gate
        self.python_executable = python_executable or sys.executable

    def verify_workspace(self, workspace: Any=None, deliverable_text: str='') -> VerificationReport:
        """Verifies whatever code a firm actually produced.

        This is the entry point tournaments use. A firm normally writes into a
        live `AgentWorkspace`; if it never did, we fall back to the fenced code
        blocks embedded in its written deliverable.

        `deliverable_text` is *only* mined for code blocks. Its prose is never
        passed to a gate, because the entire point of this harness is that an
        essay about OpenTelemetry cannot satisfy the telemetry gate.
        """
        bundle = {}
        source = 'bundle'

        # Try to get bundle from workspace object
        if workspace is not None:
            # Assume workspace has a method to get files or is a dict-like
            if hasattr(workspace, 'get_files'):
                bundle = workspace.get_files()
                source = 'workspace'
            elif isinstance(workspace, dict):
                bundle = workspace
                source = 'workspace_dict'
            elif hasattr(workspace, 'files'):
                bundle = workspace.files
                source = 'workspace_attr'

        # Fallback to deliverable text if bundle is empty
        if not bundle and deliverable_text:
            bundle = extract_code_blocks(deliverable_text)
            source = 'deliverable'

        if not bundle:
            # Empty workspace
            return self._empty_report(source)

        return self.verify_bundle(bundle, source=source)

    def _empty_report(self, source: str) -> VerificationReport:
        gates = [
            GateResult(name='syntax', status=FAILED, method='ast_parse', detail='No Python files found'),
            GateResult(name='build', status=FAILED, method='metadata_check', detail='No build metadata found'),
            GateResult(name='smoke', status=FAILED, method='import_check', detail='No modules to import'),
            GateResult(name='tests', status=FAILED, method='pytest_run', detail='No tests found'),
            GateResult(name='telemetry', status=FAILED, method='ast_analysis', detail='No telemetry usage found'),
        ]
        return VerificationReport(
            gates=gates,
            score_penalty=len(gates) * self.penalty_per_gate,
            authored_files=0,
            python_files=0,
            source=source
        )

    def verify_bundle(self, bundle: Dict[str, str], source: str='bundle') -> VerificationReport:
        """Verifies an in-memory path->content map by writing it to a temp dir."""
        # Filter bundle to remove generated/malformed paths
        clean_bundle = filter_bundle(bundle)

        # Count files
        authored_files = len(clean_bundle)
        python_files = sum(1 for p in clean_bundle if p.endswith('.py'))

        with tempfile.TemporaryDirectory() as tmpdir:
            # Write files to temp dir
            for path, content in clean_bundle.items():
                full_path = os.path.join(tmpdir, path)
                os.makedirs(os.path.dirname(full_path), exist_ok=True)
                with open(full_path, 'w', encoding='utf-8') as f:
                    f.write(content)

            return self.verify_directory(tmpdir, authored=clean_bundle, source=source)

    def verify_directory(self, workdir: str, authored: Optional[Dict[str, str]]=None, source: str='directory') -> VerificationReport:
        """Verifies an existing workspace directory."""
        if authored is None:
            # Scan directory
            authored = {}
            for root, dirs, files in os.walk(workdir):
                # Filter out excluded dirs
                dirs[:] = [d for d in dirs if not is_generated_path(os.path.join(root, d))]
                for file in files:
                    full_path = os.path.join(root, file)
                    rel_path = os.path.relpath(full_path, workdir)
                    if not is_generated_path(rel_path) and not is_malformed_path(rel_path):
                        try:
                            with open(full_path, 'r', encoding='utf-8') as f:
                                authored[rel_path] = f.read()
                        except Exception:
                            pass

        authored_files = len(authored)
        python_files = sum(1 for p in authored if p.endswith('.py'))

        gates = []

        # 1. Syntax Gate
        gates.append(self._gate_syntax(workdir, authored))

        # 2. Build Gate
        gates.append(self._gate_build(workdir, authored))

        # 3. Smoke Gate
        gates.append(self._gate_smoke(workdir, authored))

        # 4. Tests Gate
        gates.append(self._gate_tests(workdir, authored))

        # 5. Telemetry Gate
        gates.append(self._gate_telemetry(workdir, authored))

        # Calculate penalty
        failed_count = sum(1 for g in gates if g.status == FAILED)
        score_penalty = failed_count * self.penalty_per_gate

        return VerificationReport(
            gates=gates,
            score_penalty=score_penalty,
            authored_files=authored_files,
            python_files=python_files,
            source=source
        )

    def _gate_syntax(self, workdir: str, authored: Dict[str, str]) -> GateResult:
        start = time.time()
        py_files = [p for p in authored if p.endswith('.py')]

        if not py_files:
            return GateResult(
                name='syntax',
                status=FAILED,
                method='ast_parse',
                detail='No Python files found',
                duration_s=time.time() - start
            )

        errors = []
        for rel_path in py_files:
            full_path = os.path.join(workdir, rel_path)
            try:
                with open(full_path, 'r', encoding='utf-8') as f:
                    content = f.read()
                ast.parse(content)
            except SyntaxError as e:
                errors.append(f"{rel_path}: {e}")
            except Exception as e:
                errors.append(f"{rel_path}: {e}")

        if errors:
            return GateResult(
                name='syntax',
                status=FAILED,
                method='ast_parse',
                detail='Syntax errors found: ' + '; '.join(errors[:5]),
                duration_s=time.time() - start,
                evidence={'errors': errors}
            )

        return GateResult(
            name='syntax',
            status=PASSED,
            method='ast_parse',
            detail=f"All {len(py_files)} Python files parsed successfully",
            duration_s=time.time() - start
        )

    def _gate_build(self, workdir: str, authored: Dict[str, str]) -> GateResult:
        start = time.time()

        # Check for metadata files
        metadata_files = ['pyproject.toml', 'setup.py', 'setup.cfg']
        found_metadata = None

        for mf in metadata_files:
            if mf in authored:
                found_metadata = mf
                break

        if not found_metadata:
            # Check if file exists on disk even if not in authored (e.g. generated)
            for mf in metadata_files:
                if os.path.exists(os.path.join(workdir, mf)):
                    found_metadata = mf
                    break

        if not found_metadata:
            return GateResult(
                name='build',
                status=FAILED,
                method='metadata_check',
                detail='No packaging metadata found (pyproject.toml, setup.py, or setup.cfg)',
                duration_s=time.time() - start
            )

        # Validate pyproject.toml if present
        if found_metadata == 'pyproject.toml':
            pyproject_path = os.path.join(workdir, 'pyproject.toml')
            try:
                with open(pyproject_path, 'rb') as f:
                    data = tomllib.load(f)

                # Must contain at least one of [project], [build-system], or [tool]
                has_project = 'project' in data
                has_build_system = 'build-system' in data
                has_tool = 'tool' in data

                if not (has_project or has_build_system or has_tool):
                    return GateResult(
                        name='build',
                        status=FAILED,
                        method='toml_validation',
                        detail='pyproject.toml is valid TOML but missing required tables ([project], [build-system], or [tool])',
                        duration_s=time.time() - start
                    )
            except Exception as e:
                return GateResult(
                    name='build',
                    status=FAILED,
                    method='toml_validation',
                    detail=f'pyproject.toml is invalid: {e}',
                    duration_s=time.time() - start
                )

        # Attempt pip install
        try:
            # Check if pip is available
            pip_check = subprocess.run(
                [self.python_executable, '-m', 'pip', '--version'],
                capture_output=True,
                timeout=10
            )
            if pip_check.returncode != 0:
                return GateResult(
                    name='build',
                    status=SKIPPED,
                    method='pip_install',
                    detail='pip not available',
                    duration_s=time.time() - start
                )

            # Run pip install -e . --no-deps --no-build-isolation
            install_cmd = [
                self.python_executable, '-m', 'pip', 'install', '-e', '.',
                '--no-deps', '--no-build-isolation'
            ]

            result = subprocess.run(
                install_cmd,
                cwd=workdir,
                capture_output=True,
                text=True,
                timeout=self.timeout_s
            )

            if result.returncode == 0:
                return GateResult(
                    name='build',
                    status=PASSED,
                    method='pip_install',
                    detail='Package installed successfully',
                    duration_s=time.time() - start
                )
            else:
                return GateResult(
                    name='build',
                    status=FAILED,
                    method='pip_install',
                    detail=f'pip install failed: {result.stderr[-500:]}',
                    duration_s=time.time() - start,
                    evidence={'stderr': result.stderr, 'stdout': result.stdout}
                )

        except subprocess.TimeoutExpired:
            return GateResult(
                name='build',
                status=FAILED,
                method='pip_install',
                detail='pip install timed out',
                duration_s=time.time() - start
            )
        except Exception as e:
            return GateResult(
                name='build',
                status=SKIPPED,
                method='pip_install',
                detail=f'Could not run pip install: {e}',
                duration_s=time.time() - start
            )

    def _gate_smoke(self, workdir: str, authored: Dict[str, str]) -> GateResult:
        start = time.time()

        # Find non-test authored modules
        # Exclude test files
        modules = []
        for rel_path in authored:
            if not rel_path.endswith('.py'):
                continue
            if 'test' in os.path.basename(rel_path).lower():
                continue
            # Convert path to module name
            # e.g. src/foo/bar.py -> foo.bar
            # We need to handle src/ prefix if present

            # Determine if it's importable
            # We will try to import it in a subprocess

            # Clean path for module name
            clean_path = rel_path.replace('\\', '/')
            if clean_path.startswith('src/'):
                clean_path = clean_path[4:]

            if clean_path.endswith('.py'):
                mod_name = clean_path[:-3].replace('/', '.')
                if mod_name: # Not empty
                    modules.append((rel_path, mod_name))

        if not modules:
            return GateResult(
                name='smoke',
                status=FAILED,
                method='import_check',
                detail='No importable non-test modules found',
                duration_s=time.time() - start
            )

        # Prepare PYTHONPATH
        src_dir = os.path.join(workdir, 'src')
        env = os.environ.copy()
        existing_path = env.get('PYTHONPATH', '')
        new_path = f"{workdir}{os.pathsep}{src_dir}{os.pathsep}{existing_path}"
        env['PYTHONPATH'] = new_path

        # Script to import modules
        script_lines = []
        for rel_path, mod_name in modules:
            script_lines.append(f"try:")
            script_lines.append(f"    import {mod_name}")
            script_lines.append(f"except ModuleNotFoundError as e:")
            script_lines.append(f"    print(f'MODULE_NOT_FOUND:{mod_name}:{e}')")
            script_lines.append(f"except Exception as e:")
            script_lines.append(f"    print(f'IMPORT_ERROR:{mod_name}:{e}')")
            script_lines.append(f"else:")
            script_lines.append(f"    print(f'OK:{mod_name}')")

        script_content = "\n".join(script_lines)

        try:
            result = subprocess.run(
                [self.python_executable, '-c', script_content],
                cwd=workdir,
                env=env,
                capture_output=True,
                text=True,
                timeout=self.timeout_s
            )

            output = result.stdout
            errors = []
            module_not_found = []
            ok_count = 0

            for line in output.splitlines():
                if line.startswith('OK:'):
                    ok_count += 1
                elif line.startswith('MODULE_NOT_FOUND:'):
                    parts = line.split(':', 2)
                    if len(parts) >= 3:
                        module_not_found.append(parts[1])
                elif line.startswith('IMPORT_ERROR:'):
                    parts = line.split(':', 2)
                    if len(parts) >= 3:
                        errors.append(f"{parts[1]}: {parts[2]}")

            if errors:
                return GateResult(
                    name='smoke',
                    status=FAILED,
                    method='import_check',
                    detail='Import errors: ' + '; '.join(errors[:5]),
                    duration_s=time.time() - start,
                    evidence={'errors': errors}
                )

            if module_not_found:
                # If all failures are ModuleNotFoundError for third-party packages, return SKIPPED
                # If some modules imported OK, we might still consider it passed? 
                # Spec: "If module imports fail solely with ModuleNotFoundError for uninstalled third-party packages... return SKIPPED"
                # If we have OK modules, it's not "solely" failing. But if the ones that failed are just missing deps, 
                # and others passed, is it passed? 
                # Spec says: "If no importable modules exist or any module fails with a syntax or runtime error, return FAILED."
                # "If module imports fail solely with ModuleNotFoundError... return SKIPPED"

                # If we have some OK and some ModuleNotFound, it's ambiguous. 
                # Usually, if the core code imports, it's a pass. If it fails due to missing deps, it's skipped.
                # Let's assume if ANY module fails with non-ModuleNotFound, it's FAILED.
                # If ALL failures are ModuleNotFound, and at least one module was attempted, it's SKIPPED.

                if ok_count > 0:
                    # Some passed, some skipped due to deps. 
                    # Strictly speaking, the gate is about "Non-test authored modules must import".
                    # If they don't import, it's not a pass. But if it's just missing deps, it's skipped.
                    # Let's return SKIPPED if there are any ModuleNotFound errors, regardless of OK count, 
                    # because the environment isn't fully ready.
                    return GateResult(
                        name='smoke',
                        status=SKIPPED,
                        method='import_check',
                        detail=f'Modules skipped due to missing dependencies: {", ".join(module_not_found)}',
                        duration_s=time.time() - start,
                        evidence={'missing_deps': module_not_found}
                    )
                else:
                    return GateResult(
                        name='smoke',
                        status=SKIPPED,
                        method='import_check',
                        detail=f'All modules skipped due to missing dependencies: {", ".join(module_not_found)}',
                        duration_s=time.time() - start,
                        evidence={'missing_deps': module_not_found}
                    )

            if ok_count == len(modules):
                return GateResult(
                    name='smoke',
                    status=PASSED,
                    method='import_check',
                    detail=f'All {ok_count} modules imported successfully',
                    duration_s=time.time() - start
                )

            # Should not reach here if logic above is correct
            return GateResult(
                name='smoke',
                status=FAILED,
                method='import_check',
                detail='Unknown import status',
                duration_s=time.time() - start
            )

        except subprocess.TimeoutExpired:
            return GateResult(
                name='smoke',
                status=FAILED,
                method='import_check',
                detail='Import check timed out',
                duration_s=time.time() - start
            )
        except Exception as exc:
            return GateResult(
                name='smoke',
                status=SKIPPED,
                method='import_check',
                detail=f'Could not run import check: {exc}',
                duration_s=time.time() - start
            )

    def _gate_tests(self, workdir: str, authored: Dict[str, str]) -> GateResult:
        start = time.time()

        # Discover test files
        test_files = []
        for rel_path in authored:
            if not rel_path.endswith('.py'):
                continue
            if 'test' in os.path.basename(rel_path).lower():
                test_files.append(rel_path)

        if not test_files:
            return GateResult(
                name='tests',
                status=FAILED,
                method='pytest_run',
                detail='No test files found',
                duration_s=time.time() - start
            )

        # Prepare PYTHONPATH
        src_dir = os.path.join(workdir, 'src')
        env = os.environ.copy()
        existing_path = env.get('PYTHONPATH', '')
        new_path = f"{workdir}{os.pathsep}{src_dir}{os.pathsep}{existing_path}"
        env['PYTHONPATH'] = new_path

        # Check if pytest is available
        try:
            pytest_check = subprocess.run(
                [self.python_executable, '-m', 'pytest', '--version'],
                capture_output=True,
                timeout=10
            )
            has_pytest = pytest_check.returncode == 0
        except Exception:
            has_pytest = False

        if has_pytest:
            # Run pytest
            # We run pytest on the test files
            cmd = [self.python_executable, '-m', 'pytest', '-v'] + test_files
            try:
                result = subprocess.run(
                    cmd,
                    cwd=workdir,
                    env=env,
                    capture_output=True,
                    text=True,
                    timeout=self.timeout_s
                )

                if result.returncode == 0:
                    return GateResult(
                        name='tests',
                        status=PASSED,
                        method='pytest_run',
                        detail='All tests passed',
                        duration_s=time.time() - start
                    )
                else:
                    # Check if failure is due to ModuleNotFoundError
                    if 'ModuleNotFoundError' in result.stderr or 'ModuleNotFoundError' in result.stdout:
                        return GateResult(
                            name='tests',
                            status=SKIPPED,
                            method='pytest_run',
                            detail='Tests skipped due to missing dependencies',
                            duration_s=time.time() - start,
                            evidence={'stderr': result.stderr[-500:]}
                        )

                    return GateResult(
                        name='tests',
                        status=FAILED,
                        method='pytest_run',
                        detail='Tests failed',
                        duration_s=time.time() - start,
                        evidence={'stderr': result.stderr[-500:], 'stdout': result.stdout[-500:]}
                    )
            except subprocess.TimeoutExpired:
                return GateResult(
                    name='tests',
                    status=FAILED,
                    method='pytest_run',
                    detail='Tests timed out',
                    duration_s=time.time() - start
                )
            except Exception as exc:
                return GateResult(
                    name='tests',
                    status=SKIPPED,
                    method='pytest_run',
                    detail=f'Could not run pytest: {exc}',
                    duration_s=time.time() - start
                )
        else:
            # Stdlib fallback
            # Run a script that imports each test file and collects/executes tests
            script_lines = [
                "import sys",
                "import unittest",
                "import importlib",
                "import traceback",
                "",
                "test_files = " + repr(test_files),
                "collected_tests = 0",
                "failed_tests = 0",
                "module_not_found = False",
                "",
                "for tf in test_files:",
                "    try:",
                "        # Convert path to module name",
                "        mod_name = tf.replace('/', '.').replace('\\\\', '.').replace('.py', '')",
                "        # Try to import",
                "        mod = importlib.import_module(mod_name)",
                "        # Find test functions and classes",
                "        for attr_name in dir(mod):",
                "            attr = getattr(mod, attr_name)",
                "            if callable(attr) and attr_name.startswith('test_'):",
                "                # Check if it's a function taking 0 args",
                "                import inspect",
                "                sig = inspect.signature(attr)",
